import * as db from './db.js?v=purchase-routines-20260928a';
import {uid,now,number,money,setCurrency,date,escape,unitLabels,units,planNeeds,shortageRows,suggestions,recipeNeeds,round,toBase} from './domain.js';
import {exportData,download} from './export.js?v=purchase-routines-20260928a';
import {icon} from './icons.js?v=inventory-20260928a';
import * as sync from './sync.js?v=purchase-routines-20260928a';
import {ADMIN_USERNAME,ADMIN_AUTH_EMAIL,ADMIN_DISPLAY_NAME} from './config.js?v=admin-20260928b';

const app=document.querySelector('#app'),overlay=document.querySelector('#overlay'),toastBox=document.querySelector('#toast');
const state={page:'dashboard',search:'',sort:'name',desc:false,pageNum:1,perPage:8,data:null,user:null,drawer:false,sync:null,cloudWorkspaces:[]};
let autoSyncStarted=false;
const icons=Object.fromEntries(['dashboard','inventory','transactions','purchases','kitchen','plans','suggestions','reports','settings'].map(name=>[name,icon(name)]));
const titles={dashboard:'نمای کلی',inventory:'موجودی انبار',transactions:'گردش موجودی',purchases:'خریدها',kitchen:'دستور پخت',plans:'برنامه غذایی',suggestions:'پیشنهاد خرید',reports:'گزارش‌ها',settings:'تنظیمات'};
const mealLabel={breakfast:'صبحانه',lunch:'ناهار',dinner:'شام',snack:'میان‌وعده'};
const txLabel={PURCHASE:'خرید',CONSUMPTION:'مصرف',MANUAL_IN:'ورود دستی',MANUAL_OUT:'خروج دستی',ADJUSTMENT:'اصلاح',RETURN:'بازگشت',WASTE:'ضایعات'};
const e=escape;
const lookup=(list,id)=>list.find(x=>x.id===id);
const val=(form,key)=>form.elements.namedItem(key)?.value?.trim()||'';
const field=(label,name,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${e(value)}" ${extra}></label>`;
const select=(label,name,options,value='',extra='')=>`<label class="field"><span>${label}</span><select name="${name}" ${extra}>${options.map(([id,text])=>`<option value="${e(id)}" ${String(id)===String(value)?'selected':''}>${e(text)}</option>`).join('')}</select></label>`;
const unitOptions=(value='')=>units.map(x=>`<option value="${x.id}" ${x.id===value?'selected':''}>${x.name}</option>`).join('');
const itemOptions=(value='')=>state.data.items.filter(x=>x.active!==false).map(x=>`<option value="${x.id}" ${x.id===value?'selected':''}>${e(x.name)} (${e(x.code)})</option>`).join('');
const actionIcon=action=>action.startsWith('export-')||action==='backup'?'download':action.startsWith('new-')?'plus':({'edit-item':'edit','delete-item':'trash','edit-recipe':'edit','edit-personnel':'edit','edit-routine':'edit','purchase-invoice':'reports','routine-purchase':'purchases','alert-purchase':'purchases','adjust-item':'transactions','finalize-purchase':'check','consume-plan':'check','categories':'inventory','restore':'transactions','save-currency':'check'})[action];
const btn=(label,action,cls='primary',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${actionIcon(action)?icon(actionIcon(action),'btn-icon'):''}<span>${label}</span></button>`;
const empty=(text,action,label)=>`<div class="empty"><span class="empty-icon">${icon('spark')}</span><strong>${text}</strong>${action?btn(label,action,'secondary'):''}</div>`;
const badge=(text,tone='neutral')=>`<span class="badge ${tone}">${text}</span>`;
const fmtQty=(qty,unit)=>`${number(qty)} <small>${e(unitLabels[unit]||unit||'')}</small>`;
const header=(title,description,actions='')=>`<div class="page-head"><div><p class="eyebrow">راه‌نما / ${e(title)}</p><h1>${e(title)}</h1><p class="muted">${e(description)}</p></div><div class="head-actions">${actions}</div></div>`;
const card=(content,cls='')=>`<section class="card ${cls}">${content}</section>`;
function toast(message,error=false){toastBox.innerHTML=`<div class="toast ${error?'error':''}">${e(message)}</div>`;setTimeout(()=>toastBox.innerHTML='',4500)}
function showModal(title,body,onSubmit,submitLabel='ذخیره'){overlay.innerHTML=`<div class="shade" data-action="close-modal"></div><div class="modal-wrap"><section class="modal" role="dialog" aria-modal="true" aria-label="${e(title)}"><div class="modal-head"><h2>${e(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="بستن">${icon('close')}</button></div><form id="dialog-form">${body}<div class="modal-actions"><button type="button" class="btn ghost" data-action="close-modal">انصراف</button><button type="submit" class="btn primary">${e(submitLabel)}</button></div></form></section></div>`;const form=overlay.querySelector('form');form.addEventListener('submit',async event=>{event.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;try{await onSubmit(form);overlay.innerHTML='';await refresh();toast('اطلاعات با موفقیت ذخیره شد.')}catch(err){toast(err.message||'خطا در ذخیره‌سازی',true)}finally{submit.disabled=false}})}
function confirmAction(title,message,action,ok='تأیید'){showModal(title,`<p class="confirm-text">${e(message)}</p>`,action,ok)}
async function refresh(){state.data=await db.snapshot();state.sync=await db.syncState();setCurrency(lookup(state.data.settings,'currency')?.value||'تومان');state.user=lookup(state.data.users,db.currentUserId());if(!state.user){renderLogin();return}render();if(!autoSyncStarted){autoSyncStarted=true;sync.startAutoSync(async result=>{await refresh();if(result.state==='conflict')toast('تعارض داده شناسایی شد؛ جزئیات در تنظیمات است.',true)})}}
async function boot(){try{await db.openDatabase();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});if(!db.currentUserId()){renderLogin();return}await refresh()}catch(err){app.innerHTML=`<div class="auth-shell"><div class="auth-card"><h1>خطا در راه‌اندازی</h1><p>${e(err.message)}</p></div></div>`}}
async function loginUser(username,password){const normalized=username.trim().toLowerCase();if(normalized!==ADMIN_USERNAME)return db.login(normalized,password);if(sync.configured()&&navigator.onLine){try{const result=await sync.signIn(ADMIN_AUTH_EMAIL,password),cloudUser=result?.user;if(!cloudUser?.id||cloudUser.email?.toLowerCase()!==ADMIN_AUTH_EMAIL)throw new Error('حساب مدیر کل معتبر نیست.');return db.upsertCloudAdmin({id:cloudUser.id,name:ADMIN_DISPLAY_NAME,username:ADMIN_USERNAME,password})}catch(cloudError){try{return await db.login(ADMIN_USERNAME,password)}catch{throw cloudError}}}return db.login(ADMIN_USERNAME,password)}
function renderLogin(){app.innerHTML=`<main class="auth-shell"><div class="auth-art"><div class="brand big"><span class="brand-mark">${icon('spark')}</span><span>راه‌نما</span></div><h1>مدیریت آشپزخانه، روشن و دقیق.</h1><p>تمام اطلاعات شما روی دستگاه در دسترس است.</p><div class="art-shape">◌ <span>◈</span> ◌</div></div><div class="auth-card"><span class="eyebrow">خوش آمدید</span><h2>ورود به راه‌نما</h2><p class="muted">برای ادامه به حساب خود وارد شوید.</p><form id="login-form">${field('نام کاربری','username','','text','required autocomplete="username"')}${field('رمز عبور','password','','password','required autocomplete="current-password"')}<button type="submit" class="btn primary wide">ورود به برنامه</button></form><p class="muted auth-note">پس از اولین ورود آنلاین، همین حساب در حالت آفلاین نیز قابل استفاده است.</p></div></main>`;app.querySelector('#login-form').onsubmit=async ev=>{ev.preventDefault();const submit=ev.target.querySelector('[type=submit]');submit.disabled=true;try{await loginUser(val(ev.target,'username'),val(ev.target,'password'));await refresh()}catch(err){toast(err.message||'ورود انجام نشد.',true)}finally{submit.disabled=false}}}
function nav(){return Object.keys(titles).map(key=>`<button class="nav-item ${state.page===key?'active':''}" data-page="${key}"><span class="nav-icon">${icons[key]}</span><span>${titles[key]}</span>${key==='suggestions'&&purchaseSuggestions().length?'<i class="nav-dot"></i>':''}</button>`).join('')}
function render(){const page=location.hash.slice(1);if(titles[page])state.page=page;const d=state.data;if(!d)return;app.innerHTML=`<div class="shell page-${state.page}"><aside class="sidebar ${state.drawer?'open':''}"><div class="brand"><span class="brand-mark">${icon('spark')}</span><div><strong>راه‌نما</strong><small>مدیریت هوشمند آشپزخانه</small></div></div><div class="sidebar-label">فضای کاری</div><nav>${nav()}</nav><div class="sidebar-bottom"><div class="offline-tag"><span class="online-dot"></span>حالت آفلاین فعال</div><div class="profile"><div class="avatar">${e((state.user?.name||'ک').slice(0,1))}</div><div><strong>${e(state.user?.name||'کاربر')}</strong><small>${e(lookup(d.roles,d.userRoles.find(x=>x.userId===state.user?.id)?.roleId)?.name||'کاربر')}</small></div><button class="icon-btn" data-action="logout" title="خروج">${icon('logout')}</button></div></div></aside><div class="main-wrap"><header class="topbar"><button class="icon-btn menu-btn" data-action="menu" aria-label="منو">${icon('menu')}</button><span class="top-title">${titles[state.page]}</span><div class="top-spacer"></div><span class="today">${date(now())}</span><button class="icon-btn notification-btn" data-action="notifications" title="اعلان‌ها">${icon('bell')}${alertCount()?'<i></i>':''}</button></header><main class="content">${pageContent()}</main></div><nav class="bottom-nav">${['dashboard','inventory','plans','purchases','settings'].map(key=>`<button data-page="${key}" class="${state.page===key?'active':''}"><span>${icons[key]}</span><small>${titles[key]}</small></button>`).join('')}</nav></div>`}
function pageContent(){return({dashboard:dashboardPage,inventory:inventoryPage,transactions:transactionsPage,purchases:purchasesPage,kitchen:kitchenPage,plans:plansPage,suggestions:suggestionsPage,reports:reportsPage,settings:()=>settingsPage()+currencyCard()+cloudCard()}[state.page]||dashboardPage)()}
function currencyCard(){return card(`<div class="section-head"><h2>واحد پول</h2></div><p class="muted">نام واحد پول در نمایش مبلغ‌ها استفاده می‌شود. قیمت‌های ثبت‌شده تبدیل نمی‌شوند.</p>${field('نام واحد پول','currency',lookup(state.data.settings,'currency')?.value||'تومان')}<div class="button-row" style="margin-top:14px">${btn('ذخیرهٔ واحد پول','save-currency')}</div>`,'currency-card')}
function cloudCard(){
  const s=state.sync||{},connected=Boolean(s.workspaceId),signedIn=sync.hasSession();
  let body;
  if(!sync.configured())body='<p class="muted">برای راه‌اندازی همگام‌سازی، نشانی پروژه و کلید عمومی Supabase را در فایل config.js وارد کنید. برنامه تا آن زمان کاملاً محلی کار می‌کند.</p>';
  else if(!signedIn)body=`<p class="muted">برای ازسرگیری همگام‌سازی، دوباره با حساب مدیر کل وارد شوید.</p><div class="button-row">${btn('ورود دوباره به حساب ابری','cloud-login','primary')}</div>`;
  else if(!connected)body=`<p class="muted">حساب ابری: ${e(sync.cloudEmail())}</p><div class="button-row">${btn('ساخت فضای کاری','cloud-create-workspace','primary')}${btn('ورود با کد دعوت','cloud-join-workspace','secondary')}${btn('فضاهای من','cloud-workspaces','ghost')}</div>${state.cloudWorkspaces.map(x=>`<div class="setting-row"><div><strong>${e(x.name)}</strong><small>${e(x.role)}</small></div><button class="btn secondary" data-action="cloud-activate" data-id="${e(x.id)}">اتصال</button></div>`).join('')}`;
  else body=`<div class="setting-row"><div><strong>فضای کاری متصل</strong><small>${e(s.workspaceId)}</small></div>${badge(s.pending?`${number(s.pending)} تغییر در انتظار`:'همگام','neutral')}</div><p class="muted">آخرین همگام‌سازی: ${s.lastSync?date(s.lastSync):'هنوز انجام نشده'}؛ هر ۵ دقیقه و هنگام بازگشت اینترنت دوباره بررسی می‌شود.</p>${s.lastError?`<p class="sync-error">${e(s.lastError)}</p>`:''}<div class="button-row">${btn('همگام‌سازی اکنون','cloud-sync-now','primary')}${btn('ساخت کد دعوت','cloud-invite','secondary')}${btn('خروج از حساب ابری','cloud-signout','ghost')}</div>`;
  return card(`<div class="section-head"><h2>همگام‌سازی دستگاه‌ها</h2></div>${body}`,'cloud-card');
}
function forecast(){const d=state.data,total=new Map();for(const plan of d.mealPlans.filter(x=>x.status==='DRAFT'&&x.date>=new Date().toISOString().slice(0,10))){try{const needs=planNeeds(d.mealPlanItems.filter(x=>x.planId===plan.id),d.recipes,d.recipeIngredients,d.items);for(const [id,q] of needs)total.set(id,round((total.get(id)||0)+q))}catch{}}return total}
function purchaseSuggestions(){return suggestions(state.data.items,forecast())}
function alertCount(){return state.data.items.filter(x=>x.active!==false&&Number(x.stock||0)<=Number(x.minimum||0)).length}
function alerts(){const d=state.data,rows=[];for(const item of d.items.filter(x=>x.active!==false&&Number(x.stock||0)<=Number(x.minimum||0)).slice(0,4))rows.push({tone:Number(item.stock)===0?'danger':'warning',text:`${item.name} ${Number(item.stock)===0?'تمام شده است':'به حداقل موجودی رسیده است'}.`});for(const suggestion of purchaseSuggestions().filter(x=>x.shortage>0).slice(0,2))rows.push({tone:'warning',text:`برای برنامه‌های آینده ${number(suggestion.shortage)} ${unitLabels[suggestion.item.unit]} ${suggestion.item.name} کمبود دارید.`});return rows}
function dashboardPage(){const d=state.data,today=new Date().toISOString().slice(0,10),todayPlans=d.mealPlans.filter(x=>x.date===today),todayLines=d.mealPlanItems.filter(x=>todayPlans.some(p=>p.id===x.planId)),valuation=d.items.reduce((sum,x)=>sum+Number(x.stock||0)*Number(x.lastPrice||0),0),low=alertCount(),critical=alerts();return `${header('نمای کلی','آنچه امروز برای آشپزخانه مهم است.',btn('ثبت خرید جدید','new-purchase')+btn('افزودن ماده','new-item','secondary'))}<div class="dashboard-grid"><div class="dash-main">${card(`<div class="section-head"><div><span class="eyebrow">هشدارهای مهم</span><h2>نیازمند توجه</h2></div>${badge(`${number(critical.length)} مورد`,critical.length?'warning':'success')}</div>${critical.length?`<div class="alert-list">${critical.map(x=>`<div class="alert-row ${x.tone}"><span class="alert-symbol">${icon('alert')}</span><span>${e(x.text)}</span></div>`).join('')}</div>`:`<div class="calm-state"><span>${icon('check')}</span><p>همه‌چیز تحت کنترل است. هشدار فعالی ندارید.</p></div>`}`,'hero-alert')}${card(`<div class="section-head"><div><span class="eyebrow">آشپزخانه</span><h2>برنامهٔ امروز</h2></div><button class="text-link" data-page="plans">مشاهدهٔ برنامه‌ها ←</button></div>${todayLines.length?`<div class="meal-list">${todayLines.map(line=>`<div class="meal-row"><span class="meal-icon">${icon(line.meal==='breakfast'?'spark':line.meal==='dinner'?'food':'kitchen')}</span><div><small>${mealLabel[line.meal]||line.meal}</small><strong>${e(lookup(d.recipes,line.recipeId)?.name||'غذای حذف‌شده')}</strong></div><span>${number(line.portions)} نفر</span></div>`).join('')}</div>`:empty('برای امروز برنامه‌ای ثبت نشده است.','new-plan','ساخت برنامه')}`)}<div class="mini-grid">${card(`<div class="section-head"><h2>خریدهای اخیر</h2><button class="text-link" data-page="purchases">همهٔ خریدها ←</button></div>${d.purchases.length?d.purchases.slice().reverse().slice(0,3).map(p=>`<div class="compact-row"><strong>${e(p.number)}</strong><span>${date(p.date)}</span>${badge(p.status==='FINAL'?'نهایی':'پیش‌نویس',p.status==='FINAL'?'success':'neutral')}</div>`).join(''):empty('هنوز خریدی ثبت نشده است.','new-purchase','ثبت خرید')}`)}${card(`<div class="section-head"><h2>کارهای سریع</h2></div><div class="quick-actions">${btn('ثبت خرید','new-purchase','secondary')}${btn('برنامه غذایی','new-plan','secondary')}${btn('اصلاح موجودی','new-adjust','secondary')}${btn('خروجی Excel','export-all','secondary')}</div>`)}</div></div><div class="dash-side"><div class="stat-grid">${stat('اقلام انبار',number(d.items.filter(x=>x.active!==false).length),'▤','green')}${stat('ارزش تقریبی موجودی',money(valuation),'◈','blue')}${stat('موجودی کم',number(low),'!','orange')}${stat('نیاز به خرید',number(purchaseSuggestions().length),'◉','purple')}</div>${card(`<div class="section-head"><div><span class="eyebrow">نگاه سریع</span><h2>وضعیت انبار</h2></div></div>${d.items.length?`<div class="progress-list">${d.items.filter(x=>x.active!==false).slice(0,5).map(item=>{const pct=Math.min(100,Number(item.stock||0)/Math.max(Number(item.maximum||item.reorder||item.minimum||1),1)*100);return `<div><div class="progress-label"><strong>${e(item.name)}</strong><span>${fmtQty(item.stock,item.unit)}</span></div><div class="progress"><i style="width:${pct}%;background:${Number(item.stock)<=Number(item.minimum)?'#d87857':'#4d8a73'}"></i></div></div>`}).join('')}</div>`:empty('هنوز ماده‌ای در انبار ثبت نشده است.','new-item','افزودن ماده')}`)}</div></div>`}
const stat=(label,value,glyph,color)=>`<div class="stat ${color}"><span class="stat-icon">${icon(({'▤':'inventory','◈':'reports','!':'alert','◉':'purchases','⇄':'transactions','♨':'kitchen'})[glyph]||'spark')}</span><small>${label}</small><strong>${value}</strong></div>`;
function inventoryPage(){const d=state.data,filtered=d.items.filter(x=>`${x.name} ${x.code} ${lookup(d.categories,x.categoryId)?.name||''}`.includes(state.search)),sorted=filtered.filter(x=>state.filter==='low'?Number(x.stock)<=Number(x.minimum):state.filter==='active'?x.active!==false:true).sort((a,b)=>String(a[state.sort]??'').localeCompare(String(b[state.sort]??''),'fa')*(state.desc?-1:1)),pages=Math.max(1,Math.ceil(sorted.length/state.perPage)),rows=sorted.slice((Math.min(state.pageNum,pages)-1)*state.perPage,Math.min(state.pageNum,pages)*state.perPage);return `${header('موجودی انبار','مواد اولیه، حدهای موجودی و قیمت‌ها در یک نگاه.',btn('افزودن ماده','new-item')+btn('دسته‌بندی‌ها','categories','secondary')+btn('خروجی Excel','export-inventory','ghost'))}${card(`<div class="table-toolbar"><div class="search-wrap"><span>${icon('search')}</span><input id="search" placeholder="جستجوی ماده، کد یا دسته…" value="${e(state.search)}"></div><div class="toolbar-actions">${select('مرتب‌سازی','sort',[['name','نام'],['code','کد'],['stock','موجودی'],['lastPrice','آخرین قیمت']],state.sort)}${select('نمایش','filter',[['all','همهٔ اقلام'],['low','کم‌موجود'],['active','فعال']],state.filter||'all')}</div></div>${d.items.length?`<div class="table-scroll"><table><thead><tr><th>ماده اولیه</th><th>دسته</th><th>موجودی</th><th>حداقل</th><th>آخرین قیمت</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>${rows.map(item=>`<tr><td><div class="name-cell"><span class="item-avatar">${e(item.name.slice(0,1))}</span><div><strong>${e(item.name)}</strong><small>${e(item.code)}</small></div></div></td><td>${e(lookup(d.categories,item.categoryId)?.name||'—')}</td><td><strong>${fmtQty(item.stock,item.unit)}</strong></td><td>${fmtQty(item.minimum,item.unit)}</td><td>${money(item.lastPrice)}</td><td>${badge(item.active===false?'غیرفعال':Number(item.stock)===0?'تمام‌شده':Number(item.stock)<=Number(item.minimum)?'کم‌موجود':'عادی',item.active===false?'neutral':Number(item.stock)===0?'danger':Number(item.stock)<=Number(item.minimum)?'warning':'success')}</td><td><div class="row-actions"><button class="icon-btn" data-action="edit-item" data-id="${item.id}" title="ویرایش" aria-label="ویرایش ${e(item.name)}">${icon('edit')}</button><button class="icon-btn" data-action="adjust-item" data-id="${item.id}" title="اصلاح موجودی" aria-label="اصلاح موجودی ${e(item.name)}">${icon('transactions')}</button><button class="icon-btn danger-action" data-action="delete-item" data-id="${item.id}" title="حذف" aria-label="حذف ${e(item.name)}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div><div class="mobile-cards">${rows.map(item=>`<div class="mobile-data-card"><div><strong>${e(item.name)}</strong>${badge(Number(item.stock)<=Number(item.minimum)?'کم‌موجود':'عادی',Number(item.stock)<=Number(item.minimum)?'warning':'success')}</div><small>${e(item.code)} · ${e(lookup(d.categories,item.categoryId)?.name||'بدون دسته')}</small><p>${fmtQty(item.stock,item.unit)}</p><div class="mobile-card-actions">${btn('ویرایش','edit-item','ghost',`data-id="${item.id}"`)}${btn('اصلاح موجودی','adjust-item','secondary',`data-id="${item.id}"`)}${btn('حذف','delete-item','danger',`data-id="${item.id}"`)}</div></div>`).join('')}</div><div class="table-footer"><span>${number(filtered.length)} قلم</span><div><button class="icon-btn" data-action="prev-page" ${state.pageNum<=1?'disabled':''}>→</button><span>${number(Math.min(state.pageNum,pages))} / ${number(pages)}</span><button class="icon-btn" data-action="next-page" ${state.pageNum>=pages?'disabled':''}>←</button></div></div>`:empty('هنوز ماده‌ای در انبار ثبت نشده است.','new-item','افزودن ماده اولیه')}`)}`}
function transactionsPage(){const d=state.data,rows=d.transactions.slice().reverse().filter(x=>`${lookup(d.items,x.itemId)?.name||''} ${x.type}`.includes(state.search));return `${header('گردش موجودی','تمام ورود، خروج و اصلاح‌های موجودی ثبت می‌شوند.',btn('اصلاح موجودی','new-adjust')+btn('خروجی Excel','export-transactions','secondary'))}${card(`<div class="table-toolbar"><div class="search-wrap"><span>${icon('search')}</span><input id="search" placeholder="جستجوی ماده یا نوع تراکنش…" value="${e(state.search)}"></div></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>تاریخ</th><th>ماده</th><th>نوع</th><th>تغییر</th><th>قبل</th><th>بعد</th><th>مرجع</th></tr></thead><tbody>${rows.slice(0,100).map(x=>`<tr><td>${date(x.createdAt)}</td><td><strong>${e(lookup(d.items,x.itemId)?.name||'—')}</strong></td><td>${badge(txLabel[x.type]||x.type,x.quantity<0?'warning':'success')}</td><td class="ltr-num">${x.quantity>0?'+':''}${fmtQty(x.quantity,x.unit)}</td><td>${fmtQty(x.before,x.unit)}</td><td>${fmtQty(x.after,x.unit)}</td><td>${e(x.note||x.sourceType||'—')}</td></tr>`).join('')}</tbody></table></div><div class="mobile-cards">${rows.slice(0,100).map(x=>`<div class="mobile-data-card"><div><strong>${e(lookup(d.items,x.itemId)?.name||'—')}</strong>${badge(txLabel[x.type]||x.type,x.quantity<0?'warning':'success')}</div><small>${date(x.createdAt)} · ${e(x.note||'')}</small><p>${x.quantity>0?'+':''}${fmtQty(x.quantity,x.unit)}</p></div>`).join('')}</div>`:empty('هنوز تراکنشی ثبت نشده است.','new-adjust','ثبت اصلاح موجودی')}`)}`}
const purchaseSourceLabel={MANUAL:'عادی',ROUTINE:'روتین',LOW_STOCK:'هشدار موجودی'};
function routineDue(routine){if(routine.active===false)return false;if(!routine.lastPurchasedDate)return true;const today=new Date(`${new Date().toISOString().slice(0,10)}T00:00:00Z`),last=new Date(`${routine.lastPurchasedDate}T00:00:00Z`);return Math.floor((today-last)/86400000)>=Math.max(1,Number(routine.intervalDays||1))}
function purchasesPage(){const d=state.data,rows=d.purchases.slice().reverse().filter(x=>`${x.number} ${x.note||''}`.includes(state.search)),routines=d.purchaseRoutines.slice().sort((a,b)=>Number(b.active!==false)-Number(a.active!==false)||a.name.localeCompare(b.name,'fa')),lowItems=d.items.filter(x=>x.active!==false&&Number(x.stock||0)<=Number(x.minimum||0));return `${header('خریدها','خریدهای روتین، هشدارهای موجودی و سوابق فاکتورها.',btn('ثبت خرید عادی','new-purchase')+btn('تعریف خرید روتین','new-routine','secondary')+btn('خروجی Excel','export-purchases','ghost'))}<div class="purchase-hubs">${card(`<div class="section-head"><div><span class="eyebrow">تکرارشونده</span><h2>خریدهای روتین</h2></div>${badge(`${number(routines.filter(routineDue).length)} سررسید`,'warning')}</div>${routines.length?`<div class="routine-grid">${routines.map(r=>{const item=lookup(d.items,r.itemId),due=routineDue(r);return `<article class="routine-card ${r.active===false?'inactive':''}"><div class="routine-icon">${icon('purchases')}</div><div><strong>${e(r.name)}</strong><small>${e(item?.name||'ماده حذف‌شده')} · هر ${number(r.intervalDays||1)} روز · ${fmtQty(r.quantity,r.unit)}</small></div>${badge(r.active===false?'غیرفعال':due?'سررسید امروز':'انجام‌شده',r.active===false?'neutral':due?'warning':'success')}<div class="routine-actions">${btn('ثبت خرید امروز','routine-purchase','primary',`data-id="${r.id}"`)}${btn('ویرایش','edit-routine','ghost',`data-id="${r.id}"`)}<button class="btn secondary small" data-action="toggle-routine" data-id="${r.id}" data-active="${r.active===false?'true':'false'}">${r.active===false?'فعال‌سازی':'غیرفعال'}</button></div></article>`}).join('')}</div>`:`<div class="purchase-empty"><span>${icon('purchases')}</span><div><strong>خرید روتینی تعریف نشده است.</strong><small>برای مواردی مثل نان روزانه یک برنامهٔ تکرارشونده بسازید.</small></div>${btn('تعریف خرید روتین','new-routine','secondary')}</div>`}`,'routine-section')}${card(`<div class="section-head"><div><span class="eyebrow">بر اساس انبار</span><h2>هشدار کمبود موجودی</h2></div>${badge(`${number(lowItems.length)} مورد`,lowItems.length?'danger':'success')}</div>${lowItems.length?`<div class="stock-alert-grid">${lowItems.map(item=>{const suggestion=suggestions([item])[0],qty=suggestion?.suggested||Math.max(1,Number(item.minimum||1)-Number(item.stock||0));return `<article class="stock-alert-card"><div><strong>${e(item.name)}</strong><small>موجودی ${fmtQty(item.stock,item.unit)} · حداقل ${fmtQty(item.minimum,item.unit)}</small></div>${badge(Number(item.stock||0)===0?'تمام‌شده':'کم‌موجود',Number(item.stock||0)===0?'danger':'warning')}${btn(`خرید ${fmtQty(qty,item.unit)}`,'alert-purchase','secondary',`data-id="${item.id}"`)}</article>`}).join('')}</div>`:`<div class="calm-state"><span>${icon('check')}</span><p>هیچ ماده‌ای به حداقل موجودی نرسیده است.</p></div>`}`,'stock-purchase-section')}</div>${card(`<div class="section-head"><div><span class="eyebrow">بایگانی</span><h2>سوابق خرید و فاکتورها</h2></div></div><div class="table-toolbar"><div class="search-wrap"><span>${icon('search')}</span><input id="search" placeholder="جستجوی شماره خرید یا توضیحات…" value="${e(state.search)}"></div></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>شماره خرید</th><th>نوع</th><th>تاریخ</th><th>اقلام</th><th>مبلغ</th><th>فاکتور</th><th>وضعیت</th><th></th></tr></thead><tbody>${rows.map(p=>{const lines=d.purchaseItems.filter(x=>x.purchaseId===p.id),total=lines.reduce((sum,x)=>sum+x.quantity*x.unitPrice,0)-Number(p.discount||0)+Number(p.tax||0);return `<tr><td><strong>${e(p.number)}</strong></td><td>${badge(purchaseSourceLabel[p.sourceType]||'عادی',p.sourceType==='ROUTINE'?'purple':p.sourceType==='LOW_STOCK'?'warning':'neutral')}</td><td>${date(p.date)}</td><td>${number(lines.length)} قلم</td><td>${money(total)}</td><td>${btn(p.invoiceImage?'مشاهده / تعویض':'افزودن','purchase-invoice',p.invoiceImage?'ghost':'secondary',`data-id="${p.id}"`)}</td><td>${badge(p.status==='FINAL'?'نهایی':'پیش‌نویس',p.status==='FINAL'?'success':'neutral')}</td><td>${p.status==='DRAFT'?btn('نهایی‌سازی','finalize-purchase','small',`data-id="${p.id}"`):''}</td></tr>`}).join('')}</tbody></table></div><div class="mobile-cards">${rows.map(p=>`<div class="mobile-data-card"><div><strong>${e(p.number)}</strong>${badge(purchaseSourceLabel[p.sourceType]||'عادی',p.sourceType==='ROUTINE'?'purple':p.sourceType==='LOW_STOCK'?'warning':'neutral')}</div><small>${date(p.date)} · ${p.invoiceImage?'فاکتور پیوست شده':'بدون فاکتور'}</small><div class="mobile-card-actions">${btn(p.invoiceImage?'مشاهده / تعویض فاکتور':'افزودن فاکتور','purchase-invoice',p.invoiceImage?'ghost':'secondary',`data-id="${p.id}"`)}${p.status==='DRAFT'?btn('نهایی‌سازی','finalize-purchase','secondary',`data-id="${p.id}"`):''}</div></div>`).join('')}</div>`:empty('هنوز خریدی ثبت نشده است.','new-purchase','ثبت اولین خرید')}`,'purchase-history')}`}
function kitchenPage(){const d=state.data;return `${header('دستور پخت','برای هر غذا مواد و تعداد پایه را مشخص کنید.',btn('دستور پخت جدید','new-recipe')+btn('خروجی Excel','export-recipes','secondary'))}${d.recipes.length?`<div class="recipe-grid">${d.recipes.map(recipe=>{const lines=d.recipeIngredients.filter(x=>x.recipeId===recipe.id),cost=lines.reduce((sum,line)=>{const item=lookup(d.items,line.itemId);if(!item)return sum;try{return sum+toBase(line.quantity*Number(line.factor||1),line.unit,item.unit)*Number(state.data.settings.find(s=>s.id==='costBasis')?.value==='average'?item.averagePrice:item.lastPrice||0)}catch{return sum}},0);return card(`<div class="recipe-art">${icon('food')}</div><div class="recipe-content"><div class="section-head"><h2>${e(recipe.name)}</h2>${badge(`${number(recipe.servings)} نفر`,'neutral')}</div><p class="muted">${lines.length?lines.map(x=>e(lookup(d.items,x.itemId)?.name||'—')).join('، '):'هنوز ماده‌ای ثبت نشده است.'}</p><div class="recipe-bottom"><span>هزینه تقریبی هر نفر <strong>${money(cost/Number(recipe.servings||1))}</strong></span>${btn('ویرایش مواد','edit-recipe','secondary',`data-id="${recipe.id}"`)}</div></div>`,'recipe-card')}).join('')}</div>`:card(empty('هنوز دستور پختی ثبت نشده است.','new-recipe','افزودن دستور پخت'))}`}
function planRoster(plan){const ids=Array.isArray(plan.personnelIds)?plan.personnelIds:state.data.personnel.filter(x=>x.active!==false).map(x=>x.id);return ids.map(id=>lookup(state.data.personnel,id)).filter(Boolean)}
function planService(plan){const roster=planRoster(plan),records=state.data.mealDeliveries.filter(x=>x.planId===plan.id&&x.kind==='PERSON'),guest=state.data.mealDeliveries.find(x=>x.planId===plan.id&&x.kind==='GUEST');return{roster,records,delivered:records.filter(x=>x.status==='DELIVERED').length,absent:records.filter(x=>x.status==='ABSENT').length,pending:Math.max(0,roster.length-records.length),guestDelivered:Number(guest?.guestDelivered||0)}}
function personnelSection(){const people=state.data.personnel.slice().sort((a,b)=>Number(b.active!==false)-Number(a.active!==false)||a.name.localeCompare(b.name,'fa')),active=people.filter(x=>x.active!==false).length;return card(`<div class="personnel-head"><div><span class="eyebrow">فهرست پایه</span><h2>پرسنل شرکت</h2><p class="muted">افراد فعال به‌صورت خودکار در برنامه‌های جدید قرار می‌گیرند.</p></div><div class="personnel-summary"><strong>${number(active)}</strong><span>نفر فعال</span>${btn('افزودن پرسنل','new-personnel','primary')}</div></div>${people.length?`<div class="personnel-grid">${people.map(person=>`<article class="person-card ${person.active===false?'inactive':''}"><div class="person-avatar">${e(person.name.slice(0,1))}</div><div class="person-info"><strong>${e(person.name)}</strong><small>${e([person.code,person.department].filter(Boolean).join(' · ')||'بدون کد و واحد')}</small></div>${badge(person.active===false?'غیرفعال':'فعال',person.active===false?'neutral':'success')}<div class="person-actions">${btn('ویرایش','edit-personnel','ghost',`data-id="${person.id}"`)}<button class="btn secondary small" data-action="toggle-personnel" data-id="${person.id}" data-active="${person.active===false?'true':'false'}"><span>${person.active===false?'فعال‌سازی':'غیرفعال'}</span></button></div></article>`).join('')}</div>`:`<div class="personnel-empty"><span>${icon('plans')}</span><div><strong>هنوز پرسنلی ثبت نشده است.</strong><small>نام افراد شرکت را اضافه کنید تا آشپز تحویل غذا را ثبت کند.</small></div></div>`}`,'personnel-section')}
function plansPage(){const d=state.data,plans=d.mealPlans.slice().sort((a,b)=>b.date.localeCompare(a.date));return `${header('برنامه غذایی','برنامه‌ریزی تعداد غذا و ثبت تحویل به پرسنل و مهمان‌ها.',btn('برنامه جدید','new-plan')+btn('افزودن پرسنل','new-personnel','secondary')+btn('خروجی Excel','export-mealPlans','ghost'))}${personnelSection()}${plans.length?`<div class="plan-list">${plans.map(plan=>{const lines=d.mealPlanItems.filter(x=>x.planId===plan.id),service=planService(plan),total=lines.reduce((n,x)=>n+Number(x.portions),0),plannedGuests=Number(plan.guestCount||0),progress=service.roster.length?Math.round(service.delivered/service.roster.length*100):0;let shortages=[];try{shortages=shortageRows(planNeeds(lines,d.recipes,d.recipeIngredients,d.items),d.items)}catch{}return card(`<div class="plan-head"><div><span class="eyebrow">${date(plan.date)}</span><h2>${number(total)} پرس برنامه‌ریزی‌شده</h2></div>${badge(plan.status==='CONSUMED'?'مصرف ثبت‌شده':'پیش‌نویس',plan.status==='CONSUMED'?'success':'neutral')}</div><div class="plan-meals">${lines.map(line=>`<div><span>${e(mealLabel[line.meal]||line.meal)}</span><strong>${e(lookup(d.recipes,line.recipeId)?.name||'—')}</strong><small>${number(line.portions)} نفر</small></div>`).join('')}</div><div class="meal-service-summary"><div><small>پرسنل</small><strong>${number(service.roster.length)}</strong></div><div class="delivered"><small>تحویل‌شده</small><strong>${number(service.delivered)}</strong></div><div class="absent"><small>غایب</small><strong>${number(service.absent)}</strong></div><div><small>در انتظار</small><strong>${number(service.pending)}</strong></div><div class="guest"><small>مهمان</small><strong>${number(service.guestDelivered)} / ${number(plannedGuests)}</strong></div></div><div class="delivery-progress"><i style="width:${progress}%"></i></div><div class="plan-service-actions">${btn('ثبت تحویل غذا','open-meal-delivery','secondary',`data-id="${plan.id}"`)}<span>${number(progress)}٪ پرسنل تحویل گرفته‌اند</span></div>${plan.expectedAbsences?`<p class="plan-note">غیبت پیش‌بینی‌شده: ${number(plan.expectedAbsences)} نفر</p>`:''}${plan.status==='DRAFT'?`<div class="plan-footer">${shortages.length?`<span class="shortage-text">! ${number(shortages.length)} ماده کسری دارد</span>`:'<span class="ok-text">✓ موجودی قابل بررسی است</span>'}${btn('ثبت مصرف','consume-plan','primary',`data-id="${plan.id}"`)}</div>`:''}`,'plan-card')}).join('')}</div>`:card(empty('هنوز برنامهٔ غذایی ثبت نشده است.','new-plan','ساخت برنامه غذایی'))}`}
function suggestionsPage(){const rows=purchaseSuggestions();return `${header('پیشنهاد خرید','بر اساس حدهای موجودی و برنامه‌های غذایی آینده.',btn('خروجی Excel','export-inventory','secondary'))}${card(rows.length?`<div class="table-scroll"><table><thead><tr><th>ماده</th><th>موجودی</th><th>نیاز آینده</th><th>کسری</th><th>خرید پیشنهادی</th><th>هزینه تقریبی</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${e(x.item.name)}</strong></td><td>${fmtQty(x.stock,x.item.unit)}</td><td>${fmtQty(x.required,x.item.unit)}</td><td>${x.shortage?badge(fmtQty(x.shortage,x.item.unit),'danger'):'—'}</td><td><strong>${fmtQty(x.suggested,x.item.unit)}</strong></td><td>${money(x.estimated)}</td></tr>`).join('')}</tbody></table></div><div class="mobile-cards">${rows.map(x=>`<div class="mobile-data-card"><div><strong>${e(x.item.name)}</strong>${badge(`خرید ${fmtQty(x.suggested,x.item.unit)}`,'warning')}</div><small>موجودی: ${fmtQty(x.stock,x.item.unit)} · نیاز: ${fmtQty(x.required,x.item.unit)}</small><p>${money(x.estimated)}</p></div>`).join('')}</div><div class="suggestion-total">هزینهٔ تخمینی کل <strong>${money(rows.reduce((s,x)=>s+x.estimated,0))}</strong></div>`:empty('در حال حاضر خرید پیشنهادی ندارید.','new-item','افزودن ماده'))}`}
function reportsPage(){const d=state.data,cons=d.transactions.filter(x=>x.type==='CONSUMPTION'),purchases=d.purchases.filter(x=>x.status==='FINAL'),spent=purchases.reduce((sum,p)=>sum+d.purchaseItems.filter(x=>x.purchaseId===p.id).reduce((s,x)=>s+x.quantity*x.unitPrice,0)-Number(p.discount||0)+Number(p.tax||0),0),byItem=d.items.map(item=>({name:item.name,qty:Math.abs(cons.filter(x=>x.itemId===item.id).reduce((s,x)=>s+x.quantity,0))})).sort((a,b)=>b.qty-a.qty).slice(0,6),max=Math.max(1,...byItem.map(x=>x.qty));return `${header('گزارش‌ها','تصویر کلی از ارزش انبار، خرید و مصرف.',btn('خروجی کامل Excel','export-all'))}<div class="report-stats">${stat('ارزش موجودی',money(d.items.reduce((s,x)=>s+Number(x.stock||0)*Number(x.lastPrice||0),0)),'◈','green')}${stat('هزینه خریدها',money(spent),'◉','blue')}${stat('تراکنش مصرف',number(cons.length),'⇄','orange')}${stat('غذاهای ثبت‌شده',number(d.recipes.length),'♨','purple')}</div><div class="report-grid">${card(`<div class="section-head"><h2>پرمصرف‌ترین مواد</h2>${btn('خروجی مصرف','export-transactions','ghost')}</div>${byItem.some(x=>x.qty)?`<div class="bar-chart">${byItem.map(x=>`<div class="bar-row"><span>${e(x.name)}</span><div><i style="width:${x.qty/max*100}%"></i></div><strong>${number(x.qty)}</strong></div>`).join('')}</div>`:empty('هنوز مصرفی ثبت نشده است.','new-plan','ساخت برنامه')}`)}${card(`<div class="section-head"><h2>خروجی داده‌ها</h2></div><p class="muted">فایل‌های Excel برای بررسی و بایگانی آماده هستند.</p><div class="export-grid">${[['inventory','انبار'],['transactions','تراکنش‌ها'],['purchases','خریدها'],['recipes','دستور پخت'],['mealPlans','برنامه غذایی'],['personnel','پرسنل'],['mealDeliveries','تحویل غذا'],['prices','تاریخچه قیمت']].map(([id,label])=>btn(`${label} ↙`,`export-${id}`,'secondary')).join('')}</div>`)}</div>`}
function settingsPage(){const d=state.data;return `${header('تنظیمات','کاربران، داده‌ها و ترجیحات برنامه.')}<div class="settings-grid">${card(`<div class="section-head"><h2>اطلاعات پایه</h2></div><div class="setting-row"><div><strong>دسته‌بندی‌ها</strong><small>${number(d.categories.length)} دسته ثبت‌شده</small></div>${btn('مدیریت','categories','secondary')}</div><div class="setting-row"><div><strong>واحدها</strong><small>واحد پایهٔ هر ماده در زمان ایجاد تعیین می‌شود.</small></div>${badge(`${number(d.units.length)} واحد`,'neutral')}</div>`)}${card(`<div class="section-head"><h2>کاربران و دسترسی</h2>${btn('کاربر جدید','new-user','secondary')}</div><p class="muted">نقش‌ها ثبت می‌شوند. در این نسخه همهٔ کاربران دسترسی یکسان دارند.</p>${d.users.map(user=>`<div class="setting-row"><div><strong>${e(user.name)}</strong><small>${e(user.username)}</small></div>${badge(e(lookup(d.roles,d.userRoles.find(x=>x.userId===user.id)?.roleId)?.name||'—'),'neutral')}</div>`).join('')}`)}${card(`<div class="section-head"><h2>ترجیحات</h2></div><div class="setting-row"><div><strong>واحد پول</strong><small>قابل تغییر در پایین صفحه</small></div>${badge(e(lookup(d.settings,'currency')?.value||'تومان'),'neutral')}</div><div class="setting-row"><div><strong>مبنای محاسبه هزینه</strong><small>برای برآورد هزینه غذا</small></div><select id="cost-basis"><option value="last" ${lookup(d.settings,'costBasis')?.value==='last'?'selected':''}>آخرین قیمت</option><option value="average" ${lookup(d.settings,'costBasis')?.value==='average'?'selected':''}>میانگین قیمت</option></select></div>`)}${card(`<div class="section-head"><h2>پشتیبان‌گیری</h2></div><p class="muted">یک نسخه از تمام داده‌ها را ذخیره کنید. فایل پشتیبان شامل اطلاعات کاربران نیز هست.</p><div class="button-row">${btn('دریافت پشتیبان','backup','primary')}${btn('بازیابی پشتیبان','restore','secondary')}</div><input type="file" id="restore-file" accept="application/json,.json" hidden>`)}${card(`<div class="section-head"><h2>تاریخچه عملیات</h2></div>${d.audit.slice().reverse().slice(0,8).map(x=>`<div class="audit-row"><span>${e(x.action)}</span><strong>${e(x.detail)}</strong><small>${date(x.createdAt)}</small></div>`).join('')||'<p class="muted">هنوز عملیاتی ثبت نشده است.</p>'}`)}</div>`}

function itemForm(item={}){const d=state.data,stockField=item.id?field('موجودی فعلی','currentStock',fmtQty(item.stock,item.unit),'text','disabled'):field('موجودی اولیه','stock',0,'number','min="0" step="any" required');showModal(item.id?'ویرایش ماده اولیه':'افزودن ماده اولیه',`<div class="form-grid">${field('نام ماده','name',item.name,'text','required')}${field('کد کالا','code',item.code,'text','required')}${select('دسته‌بندی','categoryId',[['','بدون دسته'],...d.categories.map(x=>[x.id,x.name])],item.categoryId)}${select('واحد پایه','unit',units.map(x=>[x.id,x.name]),item.unit||'g')}${stockField}${field('حداقل موجودی','minimum',item.minimum||0,'number','min="0" step="any"')}${field('نقطه سفارش','reorder',item.reorder||0,'number','min="0" step="any"')}${field('حداکثر پیشنهادی','maximum',item.maximum||0,'number','min="0" step="any"')}${select('وضعیت','active',[['true','فعال'],['false','غیرفعال']],item.active===false?'false':'true')}</div>${item.id?'<p class="form-hint">برای تغییر مقدار موجودی از گزینهٔ «اصلاح موجودی» استفاده کنید.</p>':''}${field('توضیحات','note',item.note||'')}`,form=>db.saveItem({id:item.id,name:val(form,'name'),code:val(form,'code'),categoryId:val(form,'categoryId'),unit:val(form,'unit'),stock:item.id?item.stock:val(form,'stock'),minimum:val(form,'minimum'),reorder:val(form,'reorder'),maximum:val(form,'maximum'),active:val(form,'active')==='true',note:val(form,'note')},db.currentUserId()))}
function simpleList(store,title,extra=''){const d=state.data;showModal(title,`<div class="simple-list">${d[store].map(x=>`<div><strong>${e(x.name)}</strong><small>${e(store==='suppliers'?x.phone||'':'')}</small></div>`).join('')||'<p class="muted">هنوز موردی ثبت نشده است.</p>'}</div>${field('نام جدید','name','','text','required')}${extra}`,form=>db.saveSimple(store,{name:val(form,'name'),phone:val(form,'phone'),note:val(form,'note')},db.currentUserId()),'افزودن')}
function adjustForm(itemId=''){const d=state.data;if(!d.items.length){toast('ابتدا یک ماده اولیه ثبت کنید.',true);return}showModal('اصلاح موجودی',`${select('ماده اولیه','itemId',d.items.map(x=>[x.id,`${x.name} — موجودی ${number(x.stock)} ${unitLabels[x.unit]}`]),itemId)}${select('نوع عملیات','type',[['MANUAL_IN','ورود دستی'],['MANUAL_OUT','خروج دستی'],['WASTE','ضایعات'],['RETURN','بازگشت'],['ADJUSTMENT','اصلاح']], 'MANUAL_IN')}${field('مقدار (در واحد پایه کالا)','quantity','','number','required min="0.001" step="any"')}${field('علت / توضیح','note','','text','required')}`,async form=>{const type=val(form,'type'),sign=['MANUAL_OUT','WASTE'].includes(type)?-1:1;await db.adjustStock(val(form,'itemId'),sign*Number(val(form,'quantity')),type,val(form,'note'),db.currentUserId())},'ثبت تغییر')}
function purchaseLine(line={}){const items=state.data.items.filter(x=>x.active!==false),selected=lookup(items,line.itemId)||items[0];return `<div class="line-item purchase-line">${select('ماده','itemId',items.map(x=>[x.id,x.name]),selected?.id)}${field('مقدار','quantity',line.quantity||1,'number','required min="0.001" step="any"')}<label class="field"><span>واحد</span><select name="unit">${unitOptions(line.unit||selected?.unit||'g')}</select></label>${field('قیمت واحد','unitPrice',line.unitPrice||'','number','required min="1" step="any"')}<button type="button" class="icon-btn remove-line" data-action="remove-line" title="حذف">${icon('close')}</button></div>`}
async function compressInvoice(file){if(!file)return'';if(!file.type.startsWith('image/'))throw new Error('فایل فاکتور باید عکس باشد.');if(file.size>12*1024*1024)throw new Error('حجم عکس فاکتور بیشتر از ۱۲ مگابایت است.');const url=URL.createObjectURL(file);try{const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('عکس فاکتور خوانده نشد.'));img.src=url}),canvas=document.createElement('canvas'),max=1280,scale=Math.min(1,max/Math.max(image.naturalWidth,image.naturalHeight));canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);let data=canvas.toDataURL('image/jpeg',.72);if(data.length>650000){const shrink=Math.min(.9,Math.sqrt(620000/data.length));const width=Math.max(1,Math.round(canvas.width*shrink)),height=Math.max(1,Math.round(canvas.height*shrink)),small=document.createElement('canvas');small.width=width;small.height=height;small.getContext('2d').drawImage(canvas,0,0,width,height);data=small.toDataURL('image/jpeg',.58)}if(data.length>700000)throw new Error('عکس فاکتور هنوز بزرگ است؛ عکس ساده‌تر یا با کیفیت کمتر انتخاب کنید.');return data}finally{URL.revokeObjectURL(url)}}
function routineForm(routine={}){const d=state.data;if(!d.items.length){toast('ابتدا یک ماده اولیه ثبت کنید.',true);return}const item=lookup(d.items,routine.itemId)||d.items[0];showModal(routine.id?'ویرایش خرید روتین':'تعریف خرید روتین',`<div class="form-grid">${field('عنوان خرید روتین','name',routine.name||'','text','required')}${select('ماده اولیه','itemId',d.items.filter(x=>x.active!==false).map(x=>[x.id,x.name]),item.id)}${field('مقدار هر بار','quantity',routine.quantity||1,'number','required min="0.001" step="any"')}<label class="field"><span>واحد</span><select name="unit">${unitOptions(routine.unit||item.unit)}</select></label>${field('تکرار هر چند روز','intervalDays',routine.intervalDays||1,'number','required min="1" step="1"')}${field('قیمت پیش‌فرض اختیاری','defaultPrice',routine.defaultPrice||0,'number','min="0" step="any"')}${select('وضعیت','active',[['true','فعال'],['false','غیرفعال']],routine.active===false?'false':'true')}</div><p class="form-hint">برای خرید روزانه مثل نان، مقدار تکرار را ۱ روز قرار دهید.</p>`,form=>db.savePurchaseRoutine({id:routine.id,name:val(form,'name'),itemId:val(form,'itemId'),quantity:val(form,'quantity'),unit:val(form,'unit'),intervalDays:val(form,'intervalDays'),defaultPrice:val(form,'defaultPrice'),active:val(form,'active')==='true'},db.currentUserId()),routine.id?'ذخیره تغییرات':'ساخت خرید روتین')}
function purchaseForm(preset={}){const d=state.data;if(!d.items.length){toast('برای ثبت خرید ابتدا یک ماده اولیه ثبت کنید.',true);return}const sourceType=preset.sourceType||'MANUAL',sourceName=purchaseSourceLabel[sourceType]||'عادی';showModal(`ثبت خرید ${sourceName}`,`<div class="purchase-source-note"><span>${icon(sourceType==='LOW_STOCK'?'alert':'purchases')}</span><div><strong>نوع خرید: ${e(sourceName)}</strong><small>${sourceType==='ROUTINE'?'از برنامهٔ خرید تکرارشونده':sourceType==='LOW_STOCK'?'بر اساس هشدار حداقل موجودی':'ثبت مستقل خرید'}</small></div></div><div class="form-grid">${field('شماره خرید','number',`PUR-${Date.now().toString().slice(-7)}`,'text','required')}${field('تاریخ میلادی (در نمایش به شمسی تبدیل می‌شود)','date',new Date().toISOString().slice(0,10),'date','required')}${field('توضیحات','note')}</div><div class="subsection-head"><h3>اقلام خرید</h3><button type="button" class="btn secondary small" data-action="add-purchase-line">+ افزودن قلم</button></div><div id="purchase-lines">${purchaseLine(preset.line||{})}</div><div class="form-grid">${field('تخفیف کل','discount',0,'number','min="0" step="any"')}${field('مالیات کل','tax',0,'number','min="0" step="any"')}</div><label class="invoice-upload"><input type="file" id="invoice-file" accept="image/*" capture="environment"><span class="invoice-upload-icon">${icon('reports')}</span><span><strong>عکس فاکتور</strong><small id="invoice-file-name">عکس بگیرید یا از گالری انتخاب کنید</small></span><span class="btn secondary small">انتخاب عکس</span></label><img id="invoice-preview" class="invoice-preview" alt="پیش‌نمایش فاکتور" hidden>`,async form=>{const lines=[...form.querySelectorAll('.purchase-line')].map(row=>({itemId:val(row,'itemId'),quantity:val(row,'quantity'),unit:val(row,'unit'),unitPrice:val(row,'unitPrice')})),file=form.querySelector('#invoice-file')?.files?.[0],invoiceImage=await compressInvoice(file);await db.savePurchase({number:val(form,'number'),date:val(form,'date'),note:val(form,'note'),discount:val(form,'discount'),tax:val(form,'tax'),sourceType,routineId:preset.routineId||null,invoiceImage,invoiceName:file?.name||''},lines,db.currentUserId())},'ذخیرهٔ پیش‌نویس')}
function purchaseInvoiceForm(purchase){showModal(`فاکتور ${e(purchase.number)}`,`${purchase.invoiceImage?`<div class="invoice-view"><img src="${e(purchase.invoiceImage)}" alt="فاکتور ${e(purchase.number)}"><small>${e(purchase.invoiceName||'عکس فاکتور فعلی')}</small></div>`:''}<label class="invoice-upload"><input type="file" id="invoice-file" accept="image/*" capture="environment" required><span class="invoice-upload-icon">${icon('reports')}</span><span><strong>${purchase.invoiceImage?'تعویض عکس فاکتور':'افزودن عکس فاکتور'}</strong><small id="invoice-file-name">عکس بگیرید یا از گالری انتخاب کنید</small></span><span class="btn secondary small">انتخاب عکس</span></label><img id="invoice-preview" class="invoice-preview" alt="پیش‌نمایش فاکتور جدید" hidden>`,async form=>{const file=form.querySelector('#invoice-file')?.files?.[0];if(!file)throw new Error('عکس فاکتور را انتخاب کنید.');await db.setPurchaseInvoice(purchase.id,await compressInvoice(file),file.name,db.currentUserId())},purchase.invoiceImage?'ذخیره عکس جدید':'ذخیره فاکتور')}
function recipeLine(line={}){return `<div class="line-item recipe-line">${select('ماده','itemId',state.data.items.map(x=>[x.id,x.name]),line.itemId)}${field('مقدار','quantity',line.quantity||1,'number','required min="0.001" step="any"')}<label class="field"><span>واحد</span><select name="unit">${unitOptions(line.unit||state.data.items[0]?.unit||'g')}</select></label>${field('ضریب','factor',line.factor||1,'number','required min="0.001" step="any"')}<button type="button" class="icon-btn remove-line" data-action="remove-line">${icon('close')}</button></div>`}
function recipeForm(recipe){if(!state.data.items.length){toast('ابتدا مواد اولیه را ثبت کنید.',true);return}const lines=recipe?state.data.recipeIngredients.filter(x=>x.recipeId===recipe.id):[];showModal(recipe?'ویرایش دستور پخت':'دستور پخت جدید',`${field('نام غذا','name',recipe?.name||'','text','required')}${field('تعداد نفرات پایه','servings',recipe?.servings||10,'number','required min="1" step="1"')}<div class="subsection-head"><h3>مواد اولیه</h3><button type="button" class="btn secondary small" data-action="add-recipe-line">+ افزودن ماده</button></div><div id="recipe-lines">${(lines.length?lines:[{}]).map(recipeLine).join('')}</div>`,async form=>{const ingredients=[...form.querySelectorAll('.recipe-line')].map(row=>({itemId:val(row,'itemId'),quantity:val(row,'quantity'),unit:val(row,'unit'),factor:val(row,'factor')}));if(!ingredients.length)throw new Error('دستور پخت باید ماده داشته باشد.');recipeNeeds(ingredients,1,1,state.data.items);await db.saveRecipe({id:recipe?.id,name:val(form,'name'),servings:val(form,'servings')},ingredients,db.currentUserId())})}
function planLine(portions=Math.max(1,state.data.personnel.filter(x=>x.active!==false).length)){return `<div class="line-item plan-line">${select('وعده','meal',Object.entries(mealLabel))}${select('غذا','recipeId',state.data.recipes.map(x=>[x.id,x.name]))}${field('تعداد غذا','portions',portions,'number','required min="1" step="1"')}<button type="button" class="icon-btn remove-line" data-action="remove-line">${icon('close')}</button></div>`}
function planForm(){if(!state.data.recipes.length){toast('ابتدا دستور پخت ثبت کنید.',true);return}const staffCount=state.data.personnel.filter(x=>x.active!==false).length;showModal('برنامه غذایی جدید',`${field('تاریخ میلادی (در نمایش به شمسی تبدیل می‌شود)','date',new Date().toISOString().slice(0,10),'date','required')}<div class="form-grid">${field('غذای اضافه برای مهمان‌ها','guestCount',0,'number','min="0" step="1"')}${field('غیبت پیش‌بینی‌شده','expectedAbsences',0,'number',`min="0" max="${staffCount}" step="1"`)}</div><div class="meal-count-hint"><strong>${number(staffCount)} پرسنل فعال</strong><span>تعداد هر وعده را با توجه به مهمان‌ها و غیبت‌ها تنظیم کنید.</span></div>${field('یادداشت','note')}<div class="subsection-head"><h3>غذاهای برنامه</h3><button type="button" class="btn secondary small" data-action="add-plan-line">+ افزودن غذا</button></div><div id="plan-lines">${planLine(Math.max(1,staffCount))}</div>`,async form=>{const lines=[...form.querySelectorAll('.plan-line')].map(row=>({meal:val(row,'meal'),recipeId:val(row,'recipeId'),portions:val(row,'portions')}));await db.saveMealPlan({date:val(form,'date'),note:val(form,'note'),guestCount:val(form,'guestCount'),expectedAbsences:val(form,'expectedAbsences')},lines,db.currentUserId())})}
function personnelForm(person={}){showModal(person.id?'ویرایش پرسنل':'افزودن پرسنل',`<div class="form-grid">${field('نام و نام خانوادگی','name',person.name||'','text','required')}${field('کد پرسنلی','code',person.code||'')}${field('بخش / واحد','department',person.department||'')}${select('وضعیت','active',[['true','فعال'],['false','غیرفعال']],person.active===false?'false':'true')}</div>`,form=>db.savePersonnel({id:person.id,name:val(form,'name'),code:val(form,'code'),department:val(form,'department'),active:val(form,'active')==='true'},db.currentUserId()))}
function mealDeliveryPanel(planId){const plan=lookup(state.data.mealPlans,planId);if(!plan){toast('برنامه غذایی پیدا نشد.',true);return}const service=planService(plan),guestCount=Number(plan.guestCount||0);showModal(`تحویل غذا — ${date(plan.date)}`,`<div class="delivery-overview"><div><small>تحویل پرسنل</small><strong>${number(service.delivered)} از ${number(service.roster.length)}</strong></div><div><small>غایب</small><strong>${number(service.absent)}</strong></div><div><small>مهمان تحویل‌شده</small><strong>${number(service.guestDelivered)} از ${number(guestCount)}</strong></div></div>${guestCount?`<div class="guest-counter"><div><strong>غذای مهمان</strong><small>تعداد غذای تحویل‌شده به مهمان‌ها</small></div><div><button type="button" class="counter-btn" data-action="guest-delivery-minus" data-plan="${plan.id}" ${service.guestDelivered<=0?'disabled':''}>−</button><strong>${number(service.guestDelivered)}</strong><button type="button" class="counter-btn" data-action="guest-delivery-plus" data-plan="${plan.id}" ${service.guestDelivered>=guestCount?'disabled':''}>+</button></div></div>`:''}<div class="delivery-list">${service.roster.length?service.roster.map(person=>{const record=service.records.find(x=>x.personId===person.id),status=record?.status||'PENDING';return `<article class="delivery-row ${status.toLowerCase()}"><div class="person-avatar">${e(person.name.slice(0,1))}</div><div class="delivery-person"><strong>${e(person.name)}</strong><small>${e([person.code,person.department].filter(Boolean).join(' · ')||'پرسنل')}</small></div><label class="delivery-check" data-action="meal-person-delivered" data-id="${person.id}" data-plan="${plan.id}"><input type="checkbox" ${status==='DELIVERED'?'checked':''}><span>${status==='DELIVERED'?'تحویل شد':'تحویل غذا'}</span></label><button type="button" class="absence-btn ${status==='ABSENT'?'active':''}" data-action="meal-person-absent" data-id="${person.id}" data-plan="${plan.id}">${status==='ABSENT'?'غایب ✓':'ثبت غیبت'}</button></article>`}).join(''):'<div class="personnel-empty"><span>!</span><div><strong>پرسنلی برای این برنامه ثبت نشده است.</strong><small>ابتدا فهرست پرسنل را تکمیل کنید.</small></div></div>'}</div>`,async()=>{},'بستن')}
function userForm(){showModal('کاربر جدید',`${field('نام و نام خانوادگی','name','','text','required')}${field('نام کاربری','username','','text','required')}${field('رمز عبور','password','','password','required minlength="8"')}${select('نقش','roleId',state.data.roles.map(x=>[x.id,x.name]))}`,form=>db.createUser({name:val(form,'name'),username:val(form,'username'),password:val(form,'password'),roleId:val(form,'roleId')},db.currentUserId()))}
function notifications(){const list=alerts();showModal('اعلان‌ها',list.length?list.map(x=>`<div class="alert-row ${x.tone}"><span class="alert-symbol">${icon('alert')}</span>${e(x.text)}</div>`).join(''):`<div class="calm-state"><span>${icon('check')}</span><p>اعلان فعالی ندارید.</p></div>`,async()=>{},'بستن')}
document.addEventListener('click',async event=>{const navButton=event.target.closest('[data-page]');if(navButton){state.page=navButton.dataset.page;state.search='';state.pageNum=1;state.drawer=false;location.hash=state.page;render();return}const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;try{if(action==='close-modal'){overlay.innerHTML='';return}if(action==='menu'){state.drawer=!state.drawer;render();return}if(action==='logout'){db.logout();sync.signOut();renderLogin();return}if(action==='notifications'){notifications();return}if(action==='new-item'){itemForm();return}if(action==='edit-item'){itemForm(lookup(state.data.items,id));return}if(action==='delete-item'){const item=lookup(state.data.items,id);if(!item)throw new Error('ماده اولیه پیدا نشد.');confirmAction('حذف ماده اولیه',`«${item.name}» و گردش‌های دستی آن حذف می‌شوند. اگر در خرید، دستور پخت یا مصرف استفاده شده باشد حذف انجام نمی‌شود.`,()=>db.deleteItem(id,db.currentUserId()),'حذف');return}if(action==='categories'){simpleList('categories','دسته‌بندی‌ها');return}if(action==='new-adjust'||action==='adjust-item'){adjustForm(id);return}if(action==='new-purchase'){purchaseForm();return}if(action==='new-routine'){routineForm();return}if(action==='edit-routine'){routineForm(lookup(state.data.purchaseRoutines,id));return}if(action==='toggle-routine'){await db.setPurchaseRoutineActive(id,target.dataset.active==='true',db.currentUserId());await refresh();return}if(action==='routine-purchase'){const routine=lookup(state.data.purchaseRoutines,id),item=lookup(state.data.items,routine?.itemId);if(!routine||!item)throw new Error('خرید روتین یا مادهٔ آن پیدا نشد.');purchaseForm({sourceType:'ROUTINE',routineId:routine.id,line:{itemId:item.id,quantity:routine.quantity,unit:routine.unit,unitPrice:routine.defaultPrice||item.lastPrice||''}});return}if(action==='alert-purchase'){const item=lookup(state.data.items,id),suggestion=item?suggestions([item])[0]:null;if(!item)throw new Error('ماده اولیه پیدا نشد.');purchaseForm({sourceType:'LOW_STOCK',line:{itemId:item.id,quantity:suggestion?.suggested||1,unit:item.unit,unitPrice:item.lastPrice||''}});return}if(action==='purchase-invoice'){const purchase=lookup(state.data.purchases,id);if(!purchase)throw new Error('خرید پیدا نشد.');purchaseInvoiceForm(purchase);return}if(action==='new-recipe'){recipeForm();return}if(action==='edit-recipe'){recipeForm(lookup(state.data.recipes,id));return}if(action==='new-plan'){planForm();return}if(action==='new-personnel'){personnelForm();return}if(action==='edit-personnel'){personnelForm(lookup(state.data.personnel,id));return}if(action==='toggle-personnel'){await db.setPersonnelActive(id,target.dataset.active==='true',db.currentUserId());await refresh();return}if(action==='open-meal-delivery'){mealDeliveryPanel(id);return}if(action==='meal-person-delivered'){const planId=target.dataset.plan,current=state.data.mealDeliveries.find(x=>x.planId===planId&&x.personId===id);await db.setMealDelivery(planId,id,current?.status==='DELIVERED'?null:'DELIVERED',db.currentUserId());await refresh();mealDeliveryPanel(planId);return}if(action==='meal-person-absent'){const planId=target.dataset.plan,current=state.data.mealDeliveries.find(x=>x.planId===planId&&x.personId===id);await db.setMealDelivery(planId,id,current?.status==='ABSENT'?null:'ABSENT',db.currentUserId());await refresh();mealDeliveryPanel(planId);return}if(action==='guest-delivery-plus'||action==='guest-delivery-minus'){const planId=target.dataset.plan,current=state.data.mealDeliveries.find(x=>x.planId===planId&&x.kind==='GUEST'),delta=action.endsWith('plus')?1:-1;await db.setGuestDelivered(planId,Number(current?.guestDelivered||0)+delta,db.currentUserId());await refresh();mealDeliveryPanel(planId);return}if(action==='new-user'){userForm();return}if(action==='add-purchase-line'){overlay.querySelector('#purchase-lines').insertAdjacentHTML('beforeend',purchaseLine());return}if(action==='add-recipe-line'){overlay.querySelector('#recipe-lines').insertAdjacentHTML('beforeend',recipeLine());return}if(action==='add-plan-line'){overlay.querySelector('#plan-lines').insertAdjacentHTML('beforeend',planLine());return}if(action==='remove-line'){const row=target.closest('.line-item');if(row.parentElement.children.length>1)row.remove();return}if(action==='finalize-purchase'){confirmAction('نهایی‌سازی خرید','پس از نهایی‌سازی، موجودی اقلام افزایش می‌یابد و سابقهٔ خرید ثبت می‌شود.',()=>db.finalizePurchase(id,db.currentUserId()),'نهایی‌سازی');return}if(action==='consume-plan'){confirmAction('ثبت مصرف برنامه','مواد لازم از موجودی کسر می‌شوند. این عملیات برای این برنامه فقط یک بار اجرا می‌شود.',()=>db.consumeMealPlan(id,db.currentUserId()),'ثبت مصرف');return}if(action==='prev-page'){state.pageNum=Math.max(1,state.pageNum-1);render();return}if(action==='next-page'){state.pageNum++;render();return}if(action.startsWith('export-')){exportData(state.data,action.slice(7));toast('فایل Excel آماده شد.');return}if(action==='backup'){download(new Blob([JSON.stringify({format:'rahnama-backup-v1',exportedAt:now(),stores:state.data},null,2)],{type:'application/json'}),`rahnama-backup-${new Date().toISOString().slice(0,10)}.json`);toast('فایل پشتیبان ذخیره شد.');return}if(action==='restore'){document.querySelector('#restore-file')?.click();return}}catch(err){toast(err.message||'عملیات انجام نشد.',true)}});
document.addEventListener('input',event=>{if(event.target.id==='search'){state.search=event.target.value;state.pageNum=1;const position=event.target.selectionStart;render();const input=document.querySelector('#search');input?.focus();input?.setSelectionRange(position,position)}});
document.addEventListener('change',async event=>{if(event.target.name==='sort'){state.sort=event.target.value;render()}if(event.target.name==='filter'){state.filter=event.target.value;render()}if(event.target.id==='cost-basis'){await db.changeSetting('costBasis',event.target.value,db.currentUserId());await refresh();toast('تنظیمات ذخیره شد.')}if(event.target.id==='invoice-file'){const file=event.target.files?.[0],preview=overlay.querySelector('#invoice-preview'),label=overlay.querySelector('#invoice-file-name');if(preview?.dataset.url)URL.revokeObjectURL(preview.dataset.url);if(file&&file.type.startsWith('image/')){const url=URL.createObjectURL(file);preview.src=url;preview.dataset.url=url;preview.hidden=false;if(label)label.textContent=`${file.name} · ${Math.ceil(file.size/1024)} کیلوبایت`}else if(preview){preview.hidden=true;if(label)label.textContent='فایل انتخاب‌شده عکس نیست.'}}if(event.target.id==='restore-file'){const file=event.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());confirmAction('بازیابی پشتیبان','همهٔ داده‌های فعلی با محتوای فایل پشتیبان جایگزین می‌شوند.',async()=>{await db.restoreBackup(data);renderLogin()},'بازیابی')}catch(err){toast('فایل پشتیبان خوانده نشد.',true)}}if(event.target.name==='itemId'){const line=event.target.closest('.line-item'),item=lookup(state.data.items,event.target.value);if(line&&item)line.querySelector('[name=unit]').value=item.unit;const form=event.target.closest('form');if(!line&&form?.querySelector('[name=unit]')&&item)form.querySelector('[name=unit]').value=item.unit}});
window.addEventListener('hashchange',()=>{if(titles[location.hash.slice(1)]){state.page=location.hash.slice(1);render()}});
document.addEventListener('click',async event=>{if(event.target.closest('[data-action="save-currency"]')){try{const value=document.querySelector('[name="currency"]')?.value.trim();if(!value)throw new Error('نام واحد پول را وارد کنید.');await db.changeSetting('currency',value,db.currentUserId());await refresh();toast('واحد پول ذخیره شد.')}catch(err){toast(err.message,true)}}});
async function requireEmptyLocalData(){for(const name of ['items','categories','purchaseRoutines','purchases','recipes','mealPlans','personnel','mealDeliveries','transactions'])if((await db.read(name)).length)throw new Error('برای پیوستن به فضای کاری موجود، این دستگاه باید دادهٔ کاری خالی داشته باشد. ابتدا پشتیبان بگیرید؛ داده‌های فعلی را می‌توانید در فضای کاری تازه وارد کنید.')}
document.addEventListener('click',async event=>{
  const target=event.target.closest('[data-action^="cloud-"]');if(!target)return;
  const action=target.dataset.action;
  try{
    if(action==='cloud-login'){showModal('ورود دوباره به حساب ابری',`${field('رمز عبور مدیر کل','password','','password','required autocomplete="current-password"')}`,async form=>{const result=await sync.signIn(ADMIN_AUTH_EMAIL,val(form,'password'));if(result?.user?.email?.toLowerCase()!==ADMIN_AUTH_EMAIL)throw new Error('حساب مدیر کل معتبر نیست.');state.cloudWorkspaces=await sync.listWorkspaces()},'ورود');return}
    if(action==='cloud-create-workspace'){showModal('فضای کاری تازه',`${field('نام فضای کاری','name','','text','required minlength="2"')}<p class="muted">داده‌های فعلی این دستگاه به فضای کاری تازه فرستاده می‌شوند.</p>`,async form=>{const id=await sync.createWorkspace(val(form,'name'));await sync.activateWorkspace(id,true);state.cloudWorkspaces=await sync.listWorkspaces()},'ساخت و اتصال');return}
    if(action==='cloud-join-workspace'){showModal('پیوستن به فضای کاری',`${field('کد دعوت','code','','text','required')}<p class="muted">کد دعوت یک‌بار مصرف است و ۷ روز اعتبار دارد.</p>`,async form=>{await requireEmptyLocalData();const id=await sync.joinWorkspace(val(form,'code'));await sync.activateWorkspace(id,false);state.cloudWorkspaces=await sync.listWorkspaces()},'پیوستن');return}
    if(action==='cloud-workspaces'){state.cloudWorkspaces=await sync.listWorkspaces();render();return}
    if(action==='cloud-activate'){await requireEmptyLocalData();await sync.activateWorkspace(target.dataset.id,false);await refresh();return}
    if(action==='cloud-sync-now'){const result=await sync.syncNow();await refresh();if(result.state!=='synced')throw new Error(result.message||'همگام‌سازی انجام نشد.');toast('داده‌ها همگام شدند.');return}
    if(action==='cloud-invite'){const code=await sync.createInvite(state.sync.workspaceId);showModal('کد دعوت',`<p class="muted">این کد را فقط برای کاربر موردنظر بفرستید. کد یک‌بار مصرف است و ۷ روز اعتبار دارد.</p><p class="invite-code">${e(code)}</p>`,async()=>{},'بستن');return}
    if(action==='cloud-signout'){sync.signOut();state.cloudWorkspaces=[];await refresh();return}
  }catch(err){toast(err.message||'ارتباط ابری انجام نشد.',true)}
});
boot();
